namespace Fanex.Razorbill.Module.Report.Controllers
{
    using System.Web.Mvc;
    using Fanex.Razorbill.Module.Core.Security;
    using Fanex.Razorbill.Module.Core.Web.Controllers;
    using Fanex.Razorbill.Module.Report.Criteria.Foobet;
    using Fanex.Razorbill.Module.Report.Services.Foobet.Impl;
    using Fanex.Razorbill.Module.Report.Services.Foobet.Interface;
    using Fanex.Razorbill.Module.Report.Utils;
    using Sunplus.Agent.Model.Entities;

    /// <summary>
    /// FOOBET controller.
    /// </summary>
    public class FoobetController : BaseController
    {
        private const string MainAction = "Index";
        private const string DateFormat = "MM/dd/yyyy";

        private readonly IFoobetService _foobetService;

        public FoobetController() :
            this(null)
        {
        }

        public FoobetController(IFoobetService foobetService)
        {
            _foobetService = foobetService ?? new FoobetService();
        }

        /// <summary>
        /// Index page.
        /// </summary>
        /// <returns>Index view.</returns>
        [HttpGet]
        [FoobetAuthentication(AuthenticateAction.AuthenticationType.Read, MainAction)]
        public ActionResult Index()
        {
            ViewBag.ReportMinDate = ReportDateTimeRange[0];
            return View("~/Areas/Report/Views/Foobet/MainReport.cshtml");
        }

        /// <summary>
        /// Get data FOOBET.
        /// </summary>
        /// <param name="criteria">The criteria.</param>
        /// <returns>
        /// List FOOBET model.
        /// </returns>
        [HttpPost]
        public JsonResult GetFoobetData(FoobetCriteria criteria)
        {
            var foobets = _foobetService.GetFoobetReport(criteria);
            return Json(foobets, JsonRequestBehavior.AllowGet);
        }

        /// <summary>
        /// Export EXCEL for FOOBET.
        /// </summary>
        /// <param name="criteria">The criteria.</param>
        /// <returns>
        /// Return EXCEL file.
        /// </returns>
        [FoobetAuthentication(AuthenticateAction.AuthenticationType.Read, MainAction)]
        public ActionResult ExportExcelFoobet(FoobetCriteria criteria)
        {
            var foobetStream = _foobetService.ExportFoobetReport(criteria);
            string fileName = string.Format(
                "FB_Financial_{0}_To_{1}.xls",
                criteria.FromDate.ToString(DateFormat),
                criteria.ToDate.ToString(DateFormat));
            
            return File(foobetStream.ToArray(), "application/vnd.ms-excel", fileName);
        }

        /// <summary>
        /// Authenticate for this controller.
        /// </summary>
        private sealed class FoobetAuthentication : AuthenticateAction
        {
            public FoobetAuthentication(AuthenticationType authenticationType, string mainAction)
                : base(authenticationType, mainAction)
            {
            }

            protected override bool GrantedRead()
            {
                return UserSession.Current != null && UserSession.Current.CustId == ReportUtils.FoobetId;
            }
        }
    }
}
